<!doctype html><html><head><meta charset="utf-8"><title>{{ $settlement->settlement_no }}</title><style>body{font-family:Arial;color:#111}table{width:100%;border-collapse:collapse;margin-top:15px}th,td{border:1px solid #aaa;padding:7px}th{background:#eee}.right{text-align:right}</style></head><body onload="window.print()"><h1>Petro Direct-New Direct Settlement</h1><h2>{{ $settlement->settlement_no }}</h2><p>Date: {{ optional($settlement->transaction_date)->format('d/m/Y') }} | Operator: {{ optional($settlement->operator)->name }} | Status: {{ $settlement->status }}</p><table><tr><th>Expected</th><th>Received</th><th>Variance</th></tr><tr><td class="right">{{ number_format($settlement->expected_total,4) }}</td><td class="right">{{ number_format($settlement->received_total,4) }}</td><td class="right">{{ number_format($settlement->variance,4) }}</td></tr></table><h3>Meter Sales</h3><table><tr><th>Pump</th><th>Sold Qty</th><th>Unit Price</th><th>Amount</th></tr>@foreach($settlement->meterSales as $r)<tr><td>{{ $r->pump_id }}</td><td>{{ number_format($r->sold_qty,3) }}</td><td>{{ number_format($r->unit_price,4) }}</td><td>{{ number_format($r->amount,4) }}</td></tr>@endforeach</table><h3>Payments</h3><table><tr><th>Type</th><th>Reference</th><th>Amount</th></tr>@foreach($settlement->payments as $r)<tr><td>{{ $r->payment_type }}</td><td>{{ $r->reference_no }}</td><td>{{ number_format($r->amount,4) }}</td></tr>@endforeach</table></body></html>
